function validate([directions]) {
  if (typeof directions !== 'string' || directions.length < 1 || directions.length > 100000) return 'directions needs 1 to 10^5 characters.';
  if (!/^[LRS]+$/.test(directions)) return "Each character must be 'L', 'R' or 'S'.";
  return null;
}

