function countCollisions(directions) {
  // Simulate in half time steps with doubled positions, so every meeting lands on a whole point.
  const cars = [...directions].map((d, i) => ({ pos: 2 * i, dir: d === 'L' ? -1 : d === 'R' ? 1 : 0 }));
  let total = 0;
  for (let step = 0; step <= 2 * cars.length + 2; step++) {
    for (const car of cars) car.pos += car.dir;
    const at = new Map();
    for (const car of cars) {
      if (!at.has(car.pos)) at.set(car.pos, []);
      at.get(car.pos).push(car);
    }
    for (const group of at.values()) {
      if (group.length < 2) continue;
      for (const car of group) {
        if (car.dir !== 0) { total++; car.dir = 0; }
      }
    }
  }
  return total;
}

