function generate(rand, size) {
  const n = size === 'large' ? 8000 + Math.floor(rand() * 2001) : 1 + Math.floor(rand() * 10);
  // Vary the mix of letters so long runs of L or R at the ends show up.
  const weights = [rand() + 0.1, rand() + 0.1, rand() * 0.6];
  const total = weights[0] + weights[1] + weights[2];
  let s = '';
  for (let i = 0; i < n; i++) {
    const r = rand() * total;
    s += r < weights[0] ? 'L' : r < weights[0] + weights[1] ? 'R' : 'S';
  }
  return [s];
}
